// ===========================================================================
//  Zeus Wizard - single-file Cloudflare Worker (no npm, no build, no GitHub)
//  Paste into  Workers & Pages > Create > Hello World > Edit code  and deploy.
//  Optional: add a Secret named SECRET (enables the one-click "private link").
//  Generated by tools/build-wizard-worker.py  -  front-end lives in web/assets/*
//
//  Features
//   - Install BPB + Zeus (D1) on Workers or Pages
//   - Deploy source: any raw GitHub / Gist / GitLab / jsDelivr link (managed in the browser)
//   - Runtime Placement: Default / Smart / Region (AWS, GCP, Azure) incl. countries
//   - Panel link name: random or custom worker name
//   - Manage panels: detect panels by their CONTENT + BINDINGS (the worker name does not
//     matter), update in place without losing settings, reapply, change placement, delete
// ===========================================================================
const WORKER_URL = 'https://raw.githubusercontent.com/Alireza58310/old-new/refs/heads/main/bbbb/worker.js';
const CF_API = 'https://api.cloudflare.com/client/v4';
const INDEX_HTML = /*__INDEX_HTML__*/ '';

const MAX_NAME = 50;
const PLACEMENT_RE = /^(aws|gcp|azure):[a-z0-9-]{3,40}$/;
const SCRIPT_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9_-]{0,62}$/;

/* ----------------------------- helpers ----------------------------------- */
function randString(charset, minLen, maxLen) {
    const length = Math.floor(Math.random() * (maxLen - minLen + 1)) + minLen;
    const arr = new Uint8Array(length);
    crypto.getRandomValues(arr);
    let s = '';
    for (let i = 0; i < length; i++) s += charset[arr[i] % charset.length];
    return s;
}
const randInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
function randSubdomain() {
    const charset = 'abcdefghijklmnopqrstuvwxyz0123456789-';
    let s;
    do { s = randString(charset, 16, 32); } while (s.startsWith('-') || s.endsWith('-'));
    return s;
}
function randCode() {
    const charset = 'abcdefghijklmnopqrstuvwxyz0123456789';
    let out = '';
    for (let i = 0, n = randInt(50, 500); i < n; i++) out += `let __var_${randString(charset, 8, 16)}_${i} = ${randInt(0, 99999)};\n`;
    for (let i = 0, n = randInt(50, 500); i < n; i++) out += `function __func_${randString(charset, 8, 16)}_${i}() { return ${randInt(0, 999)}; }\n`;
    return out;
}
const today = () => new Date().toISOString().split('T')[0];

const enc = new TextEncoder(), dec = new TextDecoder();
async function aesKey(secret) {
    const hash = await crypto.subtle.digest('SHA-256', enc.encode(secret));
    return crypto.subtle.importKey('raw', hash, 'AES-GCM', false, ['encrypt', 'decrypt']);
}
async function encrypt(text, secret) {
    const key = await aesKey(secret), iv = crypto.getRandomValues(new Uint8Array(12));
    const data = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(text)));
    const all = new Uint8Array(iv.length + data.length);
    all.set(iv); all.set(data, iv.length);
    return btoa(String.fromCharCode(...all));
}
async function decrypt(b64, secret) {
    try {
        const key = await aesKey(secret), bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
        return dec.decode(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: bytes.slice(0, 12) }, key, bytes.slice(12)));
    } catch { throw new Error('The private link is invalid or SECRET changed. Open the wizard main page and use a new token.'); }
}

function createStreamLogger() {
    const { readable, writable } = new TransformStream();
    const writer = writable.getWriter(), e = new TextEncoder();
    const send = (type, message) => writer.write(e.encode(JSON.stringify({ type, message }) + '\n'));
    return {
        readable,
        success: m => send('success', m), info: m => send('info', m), warn: m => send('warn', m),
        error: m => send('error', m), complete: m => send('complete', m),
        close: () => writer.close()
    };
}

/* worker / project name typed by the user -> a safe slug (a-z, 0-9, -) */
function sanitizeName(raw) {
    if (!raw || typeof raw !== 'string') return '';
    let n = raw.trim().toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '');
    if (n.length > MAX_NAME) n = n.slice(0, MAX_NAME).replace(/-+$/g, '');
    return n;
}

/* ---------------------------- deploy source ------------------------------ */
// Accepts raw links and converts the "blob" links people usually copy from the browser.
function normalizeSourceUrl(raw) {
    const s = String(raw ?? '').trim();
    if (!s) return WORKER_URL;
    let u;
    try { u = new URL(s); } catch { throw new Error('The source link is not a valid URL.'); }
    if (u.protocol !== 'https:') throw new Error('The source link must start with https://');
    const host = u.hostname.toLowerCase();
    if (host === 'raw.githubusercontent.com' || host === 'gist.githubusercontent.com' || host === 'cdn.jsdelivr.net') return u.origin + u.pathname + u.search;
    if (host === 'github.com') {
        const m = u.pathname.match(/^\/([^/]+)\/([^/]+)\/(?:blob|raw)\/(.+)$/);
        if (!m) throw new Error('This GitHub link does not point to a file (expected github.com/user/repo/blob/branch/file.js).');
        return `https://raw.githubusercontent.com/${m[1]}/${m[2]}/${m[3]}`;
    }
    if (host === 'gitlab.com') {
        const m = u.pathname.match(/^\/(.+?)\/-\/(?:blob|raw)\/(.+)$/);
        if (!m) throw new Error('This GitLab link does not point to a file.');
        return `https://gitlab.com/${m[1]}/-/raw/${m[2]}`;
    }
    throw new Error('Allowed source hosts: raw.githubusercontent.com, github.com (blob links), gist.githubusercontent.com, gitlab.com, cdn.jsdelivr.net');
}

function detectVersion(text) {
    const pats = [
        /CURRENT_VERSION\s*[=:]\s*['"]v?([0-9][0-9.]*)['"]/i,
        /id=["']panel-version["'][^>]*>\s*v?([0-9][0-9.]*)\s*</i,
        /\bPANEL_VERSION\s*[=:]\s*['"]v?([0-9][0-9.]*)['"]/i,
        /\bVERSION\s*=\s*['"]v?([0-9]+\.[0-9][0-9.]*)['"]/
    ];
    for (const re of pats) { const m = re.exec(text); if (m) return 'v' + m[1]; }
    return '';
}

async function fetchSource(raw) {
    const url = normalizeSourceUrl(raw);
    const res = await fetch(`${url}${url.includes('?') ? '&' : '?'}t=${Date.now()}`, { headers: { 'Cache-Control': 'no-cache' } });
    if (!res.ok) throw new Error(`Failed to get panel script: status ${res.status} at ${url}`);
    const script = await res.text();
    if (!script.startsWith('Object.assign(globalThis') && !script.includes('EMBEDED_SETTINGS')) throw new Error(`The downloaded file is not a panel build (${url}).`);
    return { script, url, version: detectVersion(script) };
}

/* ------------------------ read what is inside a panel -------------------- */
// The first `const EMBEDED_SETTINGS = {...}` of a build made by this wizard; parsed with a string-aware brace scanner.
function extractEmbedded(text) {
    const m = /const\s+EMBEDED_SETTINGS\s*=\s*\{/.exec(text || '');
    if (!m) return null;
    const start = m.index + m[0].length - 1;
    let depth = 0, inStr = false, esc = false;
    for (let k = start; k < text.length && k < start + 30000; k++) {
        const c = text[k];
        if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
        if (c === '"') inStr = true;
        else if (c === '{') depth++;
        else if (c === '}' && --depth === 0) { try { return JSON.parse(text.slice(start, k + 1)); } catch { return null; } }
    }
    return null;
}
function detectBuildDate(text) {
    const m = /^\/\/ Build: (\S+)/m.exec((text || '').slice(0, 400));
    return m ? m[1] : '';
}

/* ----------------------------- placement --------------------------------- */
// '' | 'default' -> none, 'smart' -> {mode:'smart'}, 'aws:us-east-1' -> {region:'aws:us-east-1'}
function parsePlacement(v) {
    const s = String(v ?? '').trim().toLowerCase();
    if (!s || s === 'default' || s === 'off') return null;
    if (s === 'smart') return { mode: 'smart' };
    if (PLACEMENT_RE.test(s)) return { region: s };
    throw new Error(`Invalid Runtime Placement value: ${v}`);
}
function cleanPlacement(p) {
    if (!p || typeof p !== 'object') return null;
    if (p.region) return { region: p.region };
    if (p.hostname) return { hostname: p.hostname };
    if (p.host) return { host: p.host };
    if (p.mode && p.mode !== 'off') return { mode: p.mode };
    return null;
}
function placementString(p) {
    p = cleanPlacement(p);
    if (!p) return '';
    if (p.region) return p.region;
    if (p.mode) return p.mode;
    if (p.hostname) return 'hostname:' + p.hostname;
    return 'host:' + p.host;
}
const looksLikePlacementError = (err) => /placement|region/i.test(err?.message ?? '');

/* ------------------------ Cloudflare REST client ------------------------- */
class CFAccount {
    constructor(token, id, email) { this.token = token; this.id = id; this.email = email; }

    static async request(token, method, path, body) {
        const res = await fetch(CF_API + path, {
            method,
            headers: { Authorization: `Bearer ${token}`, ...(body instanceof FormData || body === undefined ? {} : { 'Content-Type': 'application/json' }) },
            body: body === undefined || body instanceof FormData ? body : JSON.stringify(body)
        });
        let data = {};
        try { data = await res.json(); } catch { }
        if (!res.ok || data.success === false) {
            const errs = Array.isArray(data.errors) ? data.errors : [];
            const err = new Error(errs.length ? errs.map(e => `${e.message ?? JSON.stringify(e)}${e.code ? ` (code ${e.code})` : ''}`).join('; ') : `HTTP ${res.status}`);
            err.code = errs[0]?.code;
            err.status = res.status;
            throw err;
        }
        return data.result;
    }

    static async create(token) {
        const v = await CFAccount.request(token, 'GET', '/user/tokens/verify');
        if (v.status !== 'active') throw new Error(`API token is ${v.status}.`);

        const accounts = await CFAccount.request(token, 'GET', '/accounts');
        if (!accounts.length) throw new Error('No account found for this token (is "Account Settings: Read" in the token?).');

        // the account e-mail is the panel login name (and is written into the worker); "admin" only if the token cannot read it
        let email = 'admin';
        try { const u = await CFAccount.request(token, 'GET', '/user'); if (u.email) email = u.email.toLowerCase(); } catch { }

        return new CFAccount(token, accounts[0].id, email);
    }

    api(method, path, body) { return CFAccount.request(this.token, method, `/accounts/${this.id}${path}`, body); }

    async nameTaken(deployType, name) {
        const exists = async (path) => (await fetch(`${CF_API}/accounts/${this.id}${path}`, { headers: { Authorization: `Bearer ${this.token}` } })).status === 200;
        try {
            if (deployType === 'pages' && await exists(`/pages/projects/${name}`)) return true;
            return await exists(`/workers/scripts/${name}`);
        } catch { return false; }
    }

    async createD1Database(workerName, deployType) {
        const base = `${workerName}-${deployType}`.slice(0, 60);
        let lastErr;
        for (let i = 0; i < 3; i++) {
            // a database with the same name may be left over from an earlier panel -> retry with a random suffix
            const name = i === 0 ? base : `${base.slice(0, 52)}-${randString('0123456789abcdef', 6, 6)}`;
            try { return (await this.api('POST', '/d1/database', { name })).uuid; }
            catch (err) {
                lastErr = err;
                if (!(err.code === 7502 || /already exists|already taken/i.test(err.message))) break;
            }
        }
        throw new Error(`Error creating D1 database (does the token have "D1: Edit"?): ${lastErr.message}`);
    }

    async getWorkersDevSubdomain() { return `${(await this.api('GET', '/workers/subdomain')).subdomain}.workers.dev`; }

    async createWorkersDevSubdomain() {
        for (let i = 0; i < 3; i++) {
            try { return (await this.api('PUT', '/workers/subdomain', { subdomain: randSubdomain() })).subdomain + '.workers.dev'; } catch { }
        }
        throw new Error('Failed to create a unique workers.dev subdomain after 3 attempts.');
    }

    /* ---- workers ---- */
    async putWorker(name, code, metadata) {
        const form = new FormData();
        form.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
        form.append('worker.js', new Blob([code], { type: 'application/javascript+module' }), 'worker.js');
        return this.api('PUT', `/workers/scripts/${name}`, form);
    }

    // uploads; if Cloudflare refuses only because of the placement value, uploads again without it and reports a warning
    async putWorkerSafe(name, code, metadata) {
        try { await this.putWorker(name, code, metadata); return ''; }
        catch (err) {
            if (!metadata.placement || !looksLikePlacementError(err)) throw err;
            const { placement, ...rest } = metadata;
            await this.putWorker(name, code, rest);
            return `Cloudflare did not accept the Runtime Placement (${placementString(placement)}): ${err.message}. The panel was uploaded with Default placement.`;
        }
    }

    async deployWorker(name, code, databaseId, placement) {
        const metadata = {
            main_module: 'worker.js',
            compatibility_date: today(),
            compatibility_flags: ['nodejs_compat'],
            bindings: [{ type: 'd1', name: 'DB', id: databaseId }]
        };
        if (placement) metadata.placement = placement;
        try { return await this.putWorkerSafe(name, code, metadata); }
        catch (err) { throw new Error(`Error deploying worker: ${err.message}`); }
    }

    enableSubdomain(name) { return this.api('POST', `/workers/scripts/${name}/subdomain`, { enabled: true, previews_enabled: true }); }

    // the deployed module(s): multipart for ES modules, plain text for service workers
    async getScriptText(name) {
        const res = await fetch(`${CF_API}/accounts/${this.id}/workers/scripts/${name}`, { headers: { Authorization: `Bearer ${this.token}` } });
        if (!res.ok) { const e = new Error(`Cannot read Worker "${name}" (HTTP ${res.status}).`); e.status = res.status; throw e; }
        if (/multipart\/form-data/i.test(res.headers.get('content-type') || '')) {
            try {
                const fd = await res.clone().formData();
                let best = '', parts = 0;
                for (const [, v] of fd) { const t = typeof v === 'string' ? v : await v.text(); parts++; if (t.length > best.length) best = t; }
                if (best) return { text: best, parts };
            } catch { }
        }
        return { text: await res.text(), parts: 1 };
    }

    // bindings + the settings we must carry over when the script is uploaded again
    async scriptSettings(name) {
        let s = null;
        try { s = await this.api('GET', `/workers/scripts/${name}/settings`); } catch { }
        let bindings = Array.isArray(s?.bindings) ? s.bindings : null;
        if (!bindings) {
            try { const b = await this.api('GET', `/workers/scripts/${name}/bindings`); if (Array.isArray(b)) bindings = b; } catch { }
        }
        return {
            bindings,
            compatibility_date: s?.compatibility_date,
            compatibility_flags: s?.compatibility_flags,
            placement: cleanPlacement(s?.placement),
            observability: s?.observability,
            limits: s?.limits
        };
    }

    /* ---- pages ---- */
    async createPagesProject(name, databaseId) {
        const project = await this.api('POST', '/pages/projects', {
            name,
            production_branch: 'main',
            deployment_configs: {
                production: {
                    compatibility_date: today(),
                    compatibility_flags: ['nodejs_compat'],
                    d1_databases: { DB: { id: databaseId } }
                }
            }
        });
        return project.subdomain ?? '';
    }

    deployPages(name, code) {
        const form = new FormData();
        form.append('manifest', '{}');
        form.append('branch', 'main');
        form.append('_worker.js', new Blob([code], { type: 'application/javascript+module' }), '_worker.js');
        return this.api('POST', `/pages/projects/${name}/deployments`, form);
    }

    // Pages Runtime Placement lives in the project's deployment configs (Pages has no metadata upload)
    async patchPagesPlacement(name, placement) {
        await this.api('PATCH', `/pages/projects/${name}`, { deployment_configs: { production: { placement }, preview: { placement } } });
    }

    async listPagesPanels() {
        const projects = await this.api('GET', '/pages/projects?per_page=100');
        return (projects ?? []).filter(p => p.deployment_configs?.production?.d1_databases?.DB).map(p => ({
            name: p.name,
            kind: 'pages',
            subdomain: p.subdomain ?? '',
            domains: p.domains ?? [],
            created: p.created_on ?? '',
            modified: p.latest_deployment?.created_on ?? '',
            d1: p.deployment_configs.production.d1_databases.DB.id ?? '',
            placement: placementString(p.deployment_configs.production.placement),
            family: 'bpb-zeus-d1',
            confidence: 'medium'
        }));
    }
}

/* ------------------------- build the deployable file --------------------- */
const pathCharset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456780-_';
const passCharset = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@$&*_-+;:,.';

function freshSettings(account, mainDomain, securePath) {
    return {
        accID: account.id, accEmail: account.email, apiToken: account.token,
        vlUUID: crypto.randomUUID(), trPass: randString(passCharset, 16, 20), securePath: securePath || randString(pathCharset, 12, 16),
        proxyIpMode: 'proxyip', proxyIPs: [], prefixes: [], fallback: '', dohUrl: '',
        mainDomain
    };
}
function buildCode(script, embeded, email) {
    return [
        `// ${email}`, `// Build: ${new Date().toISOString()}`, '// @ts-nocheck',
        `${randCode()}const EMBEDED_SETTINGS = ${JSON.stringify(embeded)};${script}`
    ].join('\n');
}
async function buildScript(account, mainDomain, sourceUrl) {
    const { script, url, version } = await fetchSource(sourceUrl);
    const embeded = freshSettings(account, mainDomain);
    return { code: buildCode(script, embeded, account.email), path: embeded.securePath, sourceUrl: url, version };
}

/* ----------------------------- deploy flows ------------------------------ */
async function resultPayload(env, account, p) {
    return { ...p, user: account.email, key: env.SECRET ? await encrypt(account.token, env.SECRET) : '' };
}

async function deployPages(env, account, workerName, databaseId, opts, { success, warn, complete }) {
    const { code, path, sourceUrl } = await buildScript(account, `${workerName}.pages.dev`, opts.sourceUrl);
    success('Script built successfully!');
    const subdomain = await account.createPagesProject(workerName, databaseId);
    success('Pages project created successfully!');
    await account.deployPages(workerName, code);
    success('Pages deployed successfully!');
    if (opts.placement) {
        try { await account.patchPagesPlacement(workerName, opts.placement); success(`Runtime Placement applied: ${placementString(opts.placement)}`); }
        catch (err) { warn(`Cloudflare did not accept the Runtime Placement for Pages (${err.message}). The panel works with Default placement.`); }
    }
    const base = `https://${subdomain}/${path}`;
    complete(JSON.stringify(await resultPayload(env, account, {
        name: workerName, kind: 'pages', label: opts.label || workerName, sourceUrl, placement: placementString(opts.placement),
        url: `${base}/panel`, zeus: `${base}/zeus`
    })));
}

async function deployWorkers(env, account, workerName, databaseId, opts, { success, warn, complete }) {
    let subdomain;
    try { subdomain = await account.getWorkersDevSubdomain(); success('Account workers subdomain is available!'); }
    catch { subdomain = await account.createWorkersDevSubdomain(); success('Fresh account, Workers subdomain created successfully!'); }

    const { code, path, sourceUrl } = await buildScript(account, `${workerName}.${subdomain}`, opts.sourceUrl);
    success('Script built successfully!');
    const warning = await account.deployWorker(workerName, code, databaseId, opts.placement);
    success('Worker deployed successfully!');
    if (warning) warn(warning); else if (opts.placement) success(`Runtime Placement applied: ${placementString(opts.placement)}`);
    await account.enableSubdomain(workerName);
    success('Worker subdomain enabled successfully!');
    const base = `https://${workerName}.${subdomain}/${path}`;
    complete(JSON.stringify(await resultPayload(env, account, {
        name: workerName, kind: 'workers', label: opts.label || workerName, sourceUrl, placement: warning ? '' : placementString(opts.placement),
        url: `${base}/panel`, zeus: `${base}/zeus`
    })));
}

/* ------------------------- panel detection / management ------------------ */
// A panel is recognised by what it IS (embedded settings + D1 "DB" binding), never by its name.
async function inspectWorker(account, name, devSub) {
    try {
        const [settings, script] = await Promise.all([
            account.scriptSettings(name).catch(() => ({ bindings: null })),
            account.getScriptText(name).catch(() => null)
        ]);
        const text = script?.text ?? '';
        const embedded = extractEmbedded(text);
        const bindings = settings.bindings ?? [];
        const d1 = bindings.find(b => b.type === 'd1' && b.name === 'DB');
        if (!embedded && !(d1 && /\bsecurePath\b/.test(text) && /\/zeus\b/.test(text))) return null;

        const securePath = embedded?.securePath ?? '';
        const host = devSub ? `${name}.${devSub}` : (embedded?.mainDomain ?? '');
        const base = host && securePath ? `https://${host}/${securePath}` : '';
        return {
            name, kind: 'workers',
            family: 'bpb-zeus-d1',
            confidence: embedded ? 'high' : 'medium',
            version: detectVersion(text),
            build: detectBuildDate(text),
            securePath,
            embeddedDomain: embedded?.mainDomain ?? '',
            email: embedded?.accEmail ?? '',
            d1: d1?.id ?? d1?.database_id ?? '',
            bindings: bindings.map(b => `${b.type}:${b.name}`),
            placement: placementString(settings.placement),
            size: text.length,
            url: base ? `${base}/panel` : '',
            zeus: base ? `${base}/zeus` : ''
        };
    } catch { return null; }
}

function bindingsForUpload(bindings) {
    // secrets are never returned by Cloudflare: they are kept through `keep_bindings`
    return bindings.filter(b => b.type !== 'secret_text' && b.type !== 'secret_key').map(b =>
        b.type === 'd1' ? { type: 'd1', name: b.name, id: b.id ?? b.database_id } : b);
}

async function updateWorkerPanel(account, name, body) {
    const mode = body.mode === 'reapply' || body.mode === 'placement' ? 'reapply' : 'update';
    const [settings, script] = await Promise.all([account.scriptSettings(name), account.getScriptText(name)]);
    if (!settings.bindings) throw new Error('Could not read the Worker bindings. Aborted so nothing is lost.');

    let code, version = '', sourceUrl = '';
    if (mode === 'reapply') {
        if (script.parts > 1) throw new Error('This Worker has several modules, it can only be updated from a source.');
        code = script.text;
        version = detectVersion(code);
    } else {
        const embedded = extractEmbedded(script.text);
        if (!embedded) throw new Error('This Worker has no readable EMBEDED_SETTINGS, so it cannot be updated in place without losing its settings. Install a fresh panel instead.');
        const src = await fetchSource(body.sourceUrl);
        if (embedded.accID === account.id) embedded.apiToken = account.token;
        code = buildCode(src.script, embedded, embedded.accEmail || account.email);
        version = src.version; sourceUrl = src.url;
    }

    const placement = body.placement === undefined || body.placement === 'keep' ? settings.placement : parsePlacement(body.placement);
    const metadata = {
        main_module: 'worker.js',
        compatibility_date: settings.compatibility_date || today(),
        compatibility_flags: settings.compatibility_flags?.length ? settings.compatibility_flags : ['nodejs_compat'],
        bindings: bindingsForUpload(settings.bindings),
        keep_bindings: ['secret_text', 'secret_key']
    };
    if (placement) metadata.placement = placement;
    if (settings.observability && typeof settings.observability.enabled === 'boolean') {
        metadata.observability = { enabled: settings.observability.enabled };
        if (typeof settings.observability.head_sampling_rate === 'number') metadata.observability.head_sampling_rate = settings.observability.head_sampling_rate;
    }
    if (settings.limits && typeof settings.limits.cpu_ms === 'number') metadata.limits = { cpu_ms: settings.limits.cpu_ms };

    const warning = await account.putWorkerSafe(name, code, metadata);
    return { name, kind: 'workers', mode, version, sourceUrl, build: detectBuildDate(code), placement: warning ? '' : placementString(placement), warning };
}

async function updatePagesPanel(account, name, body) {
    const project = await account.api('GET', `/pages/projects/${name}`);
    const placementOnly = body.mode === 'placement' || body.mode === 'reapply';
    let warning = '', url = '', zeus = '', regenerated = false, version = '', sourceUrl = '';

    if (!placementOnly) {
        // The deployed _worker.js of a Pages project cannot be downloaded, so the embedded settings cannot be read back.
        // The panel path is kept when the browser knows it (saved link); UUID / password are regenerated.
        const keepPath = typeof body.securePath === 'string' && /^[A-Za-z0-9_-]{6,40}$/.test(body.securePath) ? body.securePath : '';
        const src = await fetchSource(body.sourceUrl);
        const embedded = freshSettings(account, project.subdomain, keepPath);
        await account.deployPages(name, buildCode(src.script, embedded, account.email));
        regenerated = true; version = src.version; sourceUrl = src.url;
        const base = `https://${project.subdomain}/${embedded.securePath}`;
        url = `${base}/panel`; zeus = `${base}/zeus`;
    }

    let placement = project.deployment_configs?.production?.placement ?? null;
    if (body.placement !== undefined && body.placement !== 'keep') {
        placement = parsePlacement(body.placement);
        try { await account.patchPagesPlacement(name, placement ?? {}); }
        catch (err) { warning = `Cloudflare did not accept the Runtime Placement for Pages (${err.message}).`; placement = null; }
    }
    return { name, kind: 'pages', mode: placementOnly ? 'placement' : 'update', version, sourceUrl, url, zeus, regenerated, placement: placementString(placement), warning };
}

async function deletePanel(account, name, body) {
    let d1 = '';
    if (body.kind === 'pages') {
        if (body.deleteDb) d1 = (await account.api('GET', `/pages/projects/${name}`).catch(() => null))?.deployment_configs?.production?.d1_databases?.DB?.id ?? '';
        await account.api('DELETE', `/pages/projects/${name}`);
    } else {
        if (body.deleteDb) { const s = await account.scriptSettings(name); d1 = s.bindings?.find(b => b.type === 'd1' && b.name === 'DB')?.id ?? ''; }
        await account.api('DELETE', `/workers/scripts/${name}?force=true`);
    }
    let dbDeleted = false, warning = '';
    if (body.deleteDb) {
        if (!d1) warning = 'The D1 database id could not be found, the database was not deleted.';
        else { try { await account.api('DELETE', `/d1/database/${d1}`); dbDeleted = true; } catch (err) { warning = `Panel deleted, but the D1 database could not be deleted: ${err.message}`; } }
    }
    return { name, deleted: true, dbDeleted, warning };
}

/* -------------------------------- router --------------------------------- */
const json = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });

async function resolveToken(url, env, body) {
    const key = url.searchParams.get('key');
    if (key) {
        if (!env.SECRET) throw new Error('Private links need a Secret named SECRET on this wizard.');
        return decrypt(key, env.SECRET);
    }
    const t = String(body?.token ?? '').trim();
    if (!t) throw new Error('API token is empty.');
    return t;
}

async function api(request, url, env, fn) {
    if (request.headers.get('Origin') !== url.origin) return new Response('Unauthorized context', { status: 403 });
    try {
        const body = await request.json().catch(() => ({}));
        return json({ success: true, ...(await fn(body)) });
    } catch (err) {
        return json({ success: false, error: err.message ?? String(err) }, 400);
    }
}
async function withAccount(url, env, body) { return CFAccount.create(await resolveToken(url, env, body)); }
function scriptName(raw) {
    const n = String(raw ?? '').trim();
    if (!SCRIPT_NAME_RE.test(n)) throw new Error('Invalid Worker / project name.');
    return n;
}

export default {
    async fetch(request, env) {
        const url = new URL(request.url);
        const post = request.method === 'POST';

        if (url.pathname === '/api/deploy' && post) {
            if (request.headers.get('Origin') !== url.origin) return new Response('Unauthorized context', { status: 403 });

            const logger = createStreamLogger();
            const { readable, info, error, success, close } = logger;

            (async () => {
                try {
                    const key = url.searchParams.get('key');
                    const form = await request.formData();
                    if (key && !env.SECRET) throw new Error('Private links need a Secret named SECRET on this wizard.');
                    const apiToken = key ? await decrypt(key, env.SECRET) : (form.get('apiToken')?.toString().trim() ?? '');
                    const deployType = form.get('deployType')?.toString() === 'pages' ? 'pages' : 'workers';
                    const opts = {
                        sourceUrl: form.get('sourceUrl')?.toString().trim() ?? '',
                        placement: parsePlacement(form.get('placement')?.toString()),
                        label: (form.get('label')?.toString() ?? '').trim().slice(0, 80)
                    };
                    const customName = form.get('customName')?.toString() ?? '';
                    const cleanName = sanitizeName(customName);
                    if (customName.trim() && !cleanName) throw new Error('The panel link name must contain Latin letters or digits.');
                    const account = await CFAccount.create(apiToken);

                    let workerName;
                    if (cleanName) {
                        if (await account.nameTaken(deployType, cleanName)) throw new Error(`The name "${cleanName}" is already used by a Worker / Pages project in this account. Choose another name.`);
                        workerName = cleanName;
                        success(`Using the link name "${workerName}"`);
                    } else {
                        do { workerName = randSubdomain(); } while (await account.nameTaken(deployType, workerName));
                    }

                    info('Installing BPB Zeus Panel...');
                    const databaseId = await account.createD1Database(workerName, deployType);
                    success('D1 database created successfully!');

                    if (deployType === 'pages') await deployPages(env, account, workerName, databaseId, opts, logger);
                    else await deployWorkers(env, account, workerName, databaseId, opts, logger);
                } catch (err) {
                    error(`Failed to install BPB Zeus Panel: ${err.message ?? err}`);
                } finally {
                    close();
                }
            })();

            return new Response(readable, { headers: { 'Content-Type': 'application/x-ndjson' } });
        }

        // test a deploy source (no token needed)
        if (url.pathname === '/api/check-source' && post) return api(request, url, env, async (body) => {
            const { script, url: finalUrl, version } = await fetchSource(body.sourceUrl);
            return { url: finalUrl, size: script.length, version };
        });

        // step 1 of the scan: account, workers.dev subdomain, every Worker name and the Pages candidates
        if (url.pathname === '/api/panels/list' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            let devSub = '';
            try { devSub = await account.getWorkersDevSubdomain(); } catch { }
            const scripts = (await account.api('GET', '/workers/scripts') ?? [])
                .map(s => ({ name: s.id, modified: s.modified_on ?? '', created: s.created_on ?? '' }))
                .sort((a, b) => String(b.modified).localeCompare(String(a.modified)));
            let pages = [], pagesError = '';
            try { pages = await account.listPagesPanels(); } catch (err) { pagesError = err.message; }
            return { account: { id: account.id, email: account.email }, devSub, scripts, pages, pagesError };
        });

        // step 2: inspect a small batch (each Worker costs 2-3 API calls, a request may only make 50 on the free plan)
        if (url.pathname === '/api/panels/inspect' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            const names = [...new Set((Array.isArray(body.names) ? body.names : []).map(scriptName))].slice(0, 8);
            const devSub = /^[a-z0-9-]+\.workers\.dev$/i.test(body.devSub ?? '') ? body.devSub : '';
            const panels = (await Promise.all(names.map(n => inspectWorker(account, n, devSub)))).filter(Boolean);
            return { checked: names.length, panels };
        });

        if (url.pathname === '/api/panels/update' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            const name = scriptName(body.name);
            return body.kind === 'pages' ? updatePagesPanel(account, name, body) : updateWorkerPanel(account, name, body);
        });

        if (url.pathname === '/api/panels/delete' && post) return api(request, url, env, async (body) => {
            const account = await withAccount(url, env, body);
            return deletePanel(account, scriptName(body.name), body);
        });

        if (url.pathname === '/' || url.pathname === '/index.html') {
            return new Response(INDEX_HTML.replaceAll('%%DEFAULT_SOURCE%%', WORKER_URL), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
        }
        return new Response('Not found', { status: 404 });
    }
};
